use serde_json::{Value, Number};

pub fn solve(input: Value) -> Value {
    let cents = input.as_i64().unwrap();
    let pounds = cents / 100;
    let remainder = cents % 100;

    let pounds_str = if pounds >= 0 {
        format!("{}.", pounds)
    } else {
        format!("-{}", -pounds)
    };

    let fractional_str = if remainder == 0 {
        String::new()
    } else {
        format!("{}.{}", remainder, "00".chars().nth(remainder.to_string().len() - 2).unwrap())
    };

    let result = format!("{}{}", pounds_str, fractional_str);
    Number::from_str(result).unwrap()
}
